"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["16173"],{48767(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.passo_na_forma_objetiva","status":422,"titulo":"O passo do lan\xe7amento s\xf3 se aplica \xe0 etapa de avalia\xe7\xe3o humana"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.passo_na_forma_objetiva","requisitos":["UNI-REQ-0175"],"oQueAconteceu":["A etapa declarou a forma `OBJETIVA` e tamb\xe9m um `passoDoLancamento`. O passo \xe9 o intervalo\\nentre duas notas que um avaliador pode digitar (por exemplo, de 0,5 em 0,5); na\\navalia\xe7\xe3o objetiva a nota sai do gabarito ou da leitora \xf3ptica e ningu\xe9m a digita, ent\xe3o\\no passo n\xe3o teria a quem se aplicar.","A recusa vale j\xe1 na grava\xe7\xe3o, tamb\xe9m em rascunho, e chega no array `errors[]`, no campo\\n`passoDoLancamento` da etapa."],"comoResolver":["Escolha um dos dois caminhos:","- se a nota \xe9 obtida por gabarito ou leitora, remova o `passoDoLancamento`;\\n- se a nota \xe9 lan\xe7ada pela banca, declare a forma como `HUMANA` e mantenha o passo, que\\n  deve dividir a nota m\xe1xima da etapa.","Se a resposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija todas antes de\\nreenviar."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);